namespace Ansary;
public sealed class FileResultContext {
 public DisplayRow Root{get;}public string Path{get;}public string[] Words{get;}public IReadOnlyList<DisplayRow> Rows{get;}
 readonly Dictionary<int,int> positions=new();
 public FileResultContext(DisplayRow root,string path,string[] words,IReadOnlyList<SearchHit> hits){Root=root;Path=path;Words=words.ToArray();var rows=new List<DisplayRow>(hits.Count);foreach(var hit in hits){if(!hit.Path.Equals(path,StringComparison.OrdinalIgnoreCase)||!hit.Words.SequenceEqual(words))throw new ArgumentException("Mixed file/search context");string text=hit.Text;int start=Math.Max(0,hit.Offset-80);if(text.Length>400)text=(start>0?"…":"")+text.Substring(start,Math.Min(400,text.Length-start))+"…";positions.Add(hit.Index,rows.Count);rows.Add(new DisplayRow{Text=$"فقرة {hit.Index+1}: {text}",Words=Words,Hit=hit,Context=this,Depth=3,Indent=new System.Windows.Thickness(12,2,0,2)});}Rows=rows.AsReadOnly();}
 public DisplayRow? Find(int paragraph)=>positions.TryGetValue(paragraph,out int at)?Rows[at]:null;
 public SearchHit? Next(int paragraph,int direction){if(!positions.TryGetValue(paragraph,out int at))return null;int next=at+direction;return next>=0&&next<Rows.Count?Rows[next].Hit:null;}
 public static void Verify(){string path="context-test.docx";var general=new[]{"بحث"};var local=new[]{"داخلي"};SearchHit Hit(int n,string[] words)=>new(){Path=path,Index=n,Text=words[0],Words=words,Length=1,Ticks=1};var a=Hit(2,general);var b=Hit(9,general);var c=Hit(5,local);var first=new FileResultContext(new DisplayRow(),path,general,new[]{a,b});var second=new FileResultContext(new DisplayRow(),path,local,new[]{c});if(first.Rows.Count!=2||second.Rows.Count!=1||first.Next(2,1)!=b||first.Next(9,-1)!=a||first.Next(9,1)!=null||second.Find(2)!=null||second.Find(5)?.Hit!=c||first.Find(2)?.Context!=first||!first.Words.SequenceEqual(general)||!second.Words.SequenceEqual(local))throw new InvalidOperationException("Viewer result context regression");var empty=new FileResultContext(new DisplayRow(),path,local,Array.Empty<SearchHit>());if(empty.Rows.Count!=0||empty.Find(2)!=null)throw new InvalidOperationException("Empty search retained old results");}
}
